import React from 'react';
import { Box } from '@mui/material';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import carouselBg from '../assets/Carousel.png';

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    arrows: true,
  };

  const slides = [
    {
      id: 1,
      image: "https://via.placeholder.com/1920x600",
      alt: "Slide 1"
    },
    {
      id: 2,
      image: "https://via.placeholder.com/1920x600",
      alt: "Slide 2"
    },
    {
      id: 3,
      image: "https://via.placeholder.com/1920x600",
      alt: "Slide 3"
    }
  ];

  return (
    <Box
      sx={{
        width: '100%',
        position: 'relative',
        '.slick-dots': {
          bottom: '20px',
          '& li button:before': {
            color: '#fff',
          },
          '& li.slick-active button:before': {
            color: '#fff',
          }
        }
      }}
    >
      <Slider {...settings}>
        {slides.map((slide) => (
          <Box
            key={slide.id}
            sx={{
              width: '100%',
              height: '600px', // Sabit bir yükseklik
              position: 'relative'
            }}
          >
            <Box
              component="img"
              src={slide.image}
              alt={slide.alt}
              sx={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
              }}
            />
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default EventsSlider;
